    15→void UCosmeticMainWindow::NativeConstruct()
    16→{
    17→	Super::NativeConstruct();
    18→
    19→	// 모드 탭 버튼 바인딩
    20→	if (ShopTabButton)
    21→	{
    22→		ShopTabButton->OnClicked.RemoveDynamic(this, &UCosmeticMainWindow::OnShopTabClicked);
    23→		ShopTabButton->OnClicked.AddDynamic(this, &UCosmeticMainWindow::OnShopTabClicked);
