    25→
    26→	if (InventoryTabButton)
    27→	{
    28→		InventoryTabButton->OnClicked.RemoveDynamic(this, &UCosmeticMainWindow::OnInventoryTabClicked);
    29→		InventoryTabButton->OnClicked.AddDynamic(this, &UCosmeticMainWindow::OnInventoryTabClicked);
    30→	}
    31→
    32→	// 슬롯 탭 버튼 바인딩
    33→	if (TabHeadButton)
    34→	{
    35→		TabHeadButton->OnClicked.RemoveDynamic(this, &UCosmeticMainWindow::OnTabHeadClicked);
    36→		TabHeadButton->OnClicked.AddDynamic(this, &UCosmeticMainWindow::OnTabHeadClicked);
    37→	}
    38→
    39→	if (TabBodyButton)
    40→	{
    41→		TabBodyButton->OnClicked.RemoveDynamic(this, &UCosmeticMainWindow::OnTabBodyClicked);
    42→		TabBodyButton->OnClicked.AddDynamic(this, &UCosmeticMainWindow::OnTabBodyClicked);
    43→	}
    44→
    45→	if (TabBackButton)
    46→	{
    47→		TabBackButton->OnClicked.RemoveDynamic(this, &UCosmeticMainWindow::OnTabBackClicked);
    48→		TabBackButton->OnClicked.AddDynamic(this, &UCosmeticMainWindow::OnTabBackClicked);
    49→	}
    50→
    51→	if (TabEffectButton)
    52→	{
    53→		TabEffectButton->OnClicked.RemoveDynamic(this, &UCosmeticMainWindow::OnTabEffectClicked);
    54→		TabEffectButton->OnClicked.AddDynamic(this, &UCosmeticMainWindow::OnTabEffectClicked);
    55→	}
    56→
    57→	// 액션/닫기 버튼 바인딩
    58→	if (ActionButton)
    59→	{
    60→		ActionButton->OnClicked.RemoveDynamic(this, &UCosmeticMainWindow::OnActionButtonClicked);
    61→		ActionButton->OnClicked.AddDynamic(this, &UCosmeticMainWindow::OnActionButtonClicked);
    62→	}
    63→
    64→	if (CloseButton)
    65→	{
    66→		CloseButton->OnClicked.RemoveDynamic(this, &UCosmeticMainWindow::OnCloseClicked);
    67→		CloseButton->OnClicked.AddDynamic(this, &UCosmeticMainWindow::OnCloseClicked);
    68→	}
    69→
    70→	// 서브시스템 델리게이트 바인딩
    71→	UGameInstance* GI = GetGameInstance();
    72→	if (GI)
    73→	{
    74→		if (UWjWorldCosmeticSubsystem* CosmeticSub = GI->GetSubsystem<UWjWorldCosmeticSubsystem>())
    75→		{
    76→			CosmeticSub->OnInventoryUpdated.RemoveDynamic(this, &UCosmeticMainWindow::OnInventoryUpdated);
    77→			CosmeticSub->OnInventoryUpdated.AddDynamic(this, &UCosmeticMainWindow::OnInventoryUpdated);
    78→			CosmeticSub->OnLoadoutChanged.RemoveDynamic(this, &UCosmeticMainWindow::OnLoadoutChanged);
    79→			CosmeticSub->OnLoadoutChanged.AddDynamic(this, &UCosmeticMainWindow::OnLoadoutChanged);
    80→		}
    81→
    82→		if (UWjWorldPurchaseSubsystem* PurchaseSub = GI->GetSubsystem<UWjWorldPurchaseSubsystem>())
    83→		{
    84→			PurchaseSub->OnPurchaseComplete.RemoveDynamic(this, &UCosmeticMainWindow::OnPurchaseComplete);
    85→			PurchaseSub->OnPurchaseComplete.AddDynamic(this, &UCosmeticMainWindow::OnPurchaseComplete);
    86→		}
    87→	}
    88→
    89→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticMainWindow: NativeConstruct completed"));
    90→}
    91→
    92→void UCosmeticMainWindow::NativeDestruct()
    93→{
    94→	// 델리게이트 바인딩 해제
    95→	UGameInstance* GI = GetGameInstance();
    96→	if (GI)
    97→	{
    98→		if (UWjWorldCosmeticSubsystem* CosmeticSub = GI->GetSubsystem<UWjWorldCosmeticSubsystem>())
    99→		{
   100→			CosmeticSub->OnInventoryUpdated.RemoveDynamic(this, &UCosmeticMainWindow::OnInventoryUpdated);
   101→			CosmeticSub->OnLoadoutChanged.RemoveDynamic(this, &UCosmeticMainWindow::OnLoadoutChanged);
   102→		}
   103→
   104→		if (UWjWorldPurchaseSubsystem* PurchaseSub = GI->GetSubsystem<UWjWorldPurchaseSubsystem>())
   105→		{
   106→			PurchaseSub->OnPurchaseComplete.RemoveDynamic(this, &UCosmeticMainWindow::OnPurchaseComplete);
   107→		}
   108→	}
   109→
   110→	ClearItemGrid();
   111→	Super::NativeDestruct();
   112→}
