   114→void UCosmeticMainWindow::ShowPopup()
   115→{
   116→	AddToViewport(100);
   117→
   118→	// 입력 모드: UI 전용
   119→	APlayerController* PC = GetWorld()->GetFirstPlayerController();
   120→	if (PC)
   121→	{
   122→		FInputModeUIOnly InputMode;
   123→		InputMode.SetLockMouseToViewportBehavior(EMouseLockMode::DoNotLock);
   124→		PC->SetInputMode(InputMode);
   125→		PC->bShowMouseCursor = true;
   126→	}
   127→
   128→	// 초기 상태 설정 및 UI 갱신
   129→	CurrentMode = ECosmeticWindowMode::Shop;
   130→	CurrentSlot = ECosmeticSlot::Head;
   131→	SelectedItemId = NAME_None;
   132→
   133→	RefreshUI();
   134→
   135→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticMainWindow: Popup shown"));
   136→}
   137→
   138→void UCosmeticMainWindow::ClosePopup()
   139→{
   140→	// 시착 취소
   141→	if (PreviewPanel)
   142→	{
   143→		PreviewPanel->ResetPreview();
   144→	}
   145→
   146→	RemoveFromParent();
   147→
   148→	// 입력 모드 복원
   149→	APlayerController* PC = GetWorld()->GetFirstPlayerController();
   150→	if (PC)
   151→	{
   152→		PC->SetInputMode(FInputModeGameAndUI());
   153→		PC->bShowMouseCursor = true;
   154→	}
   155→
   156→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticMainWindow: Popup closed"));
   157→}
