   285→void UCosmeticMainWindow::OnPurchaseComplete(FName ItemId, bool bSuccess)
   286→{
   287→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticMainWindow: Purchase %s for %s"), bSuccess ? TEXT("succeeded") : TEXT("failed"), *ItemId.ToString());
   288→	RefreshUI();
   289→}
