   291→void UCosmeticMainWindow::RefreshUI()
   292→{
   293→	UpdateTabStyles();
   294→	RefreshItemGrid();
   295→	RefreshDetailInfo();
   296→	RefreshActionButton();
   297→}
   298→
   299→void UCosmeticMainWindow::RefreshItemGrid()
   300→{
   301→	ClearItemGrid();
   302→
   303→	if (CurrentMode == ECosmeticWindowMode::Shop)
   304→	{
   305→		PopulateShopItems();
   306→	}
   307→	else
   308→	{
   309→		PopulateInventoryItems();
   310→	}
   311→}
   312→
   313→void UCosmeticMainWindow::RefreshDetailInfo()
   314→{
   315→	if (SelectedItemId.IsNone())
   316→	{
   317→		if (SelectedItemNameText)
   318→		{
   319→			SelectedItemNameText->SetText(FText::GetEmpty());
   320→		}
   321→		if (SelectedItemDescriptionText)
   322→		{
   323→			SelectedItemDescriptionText->SetText(FText::GetEmpty());
   324→		}
   325→		if (SelectedItemPriceText)
   326→		{
   327→			SelectedItemPriceText->SetText(FText::GetEmpty());
   328→		}
   329→		return;
   330→	}
   331→
   332→	UGameInstance* GI = GetGameInstance();
   333→	if (!GI)
   334→	{
   335→		return;
   336→	}
   337→
   338→	UWjWorldCosmeticSubsystem* CosmeticSub = GI->GetSubsystem<UWjWorldCosmeticSubsystem>();
   339→	if (!CosmeticSub || !CosmeticSub->GetCatalog())
   340→	{
   341→		return;
   342→	}
   343→
   344→	const FCosmeticItemDefinition* ItemDef = CosmeticSub->GetCatalog()->FindByItemId(SelectedItemId);
   345→	if (!ItemDef)
   346→	{
   347→		return;
   348→	}
   349→
   350→	if (SelectedItemNameText)
   351→	{
   352→		SelectedItemNameText->SetText(ItemDef->DisplayName);
   353→	}
   354→
   355→	if (SelectedItemDescriptionText)
   356→	{
   357→		SelectedItemDescriptionText->SetText(ItemDef->Description);
   358→	}
   359→
   360→	if (SelectedItemPriceText)
   361→	{
   362→		if (CosmeticSub->HasItem(SelectedItemId))
   363→		{
   364→			SelectedItemPriceText->SetText(NSLOCTEXT("Cosmetic", "Owned", "보유중"));
   365→		}
   366→		else if (ItemDef->Price > 0)
   367→		{
   368→			SelectedItemPriceText->SetText(FText::Format(NSLOCTEXT("Cosmetic", "PriceFormat", "{0}"), FText::AsNumber(ItemDef->Price)));
   369→		}
   370→		else
   371→		{
   372→			SelectedItemPriceText->SetText(NSLOCTEXT("Cosmetic", "Free", "무료"));
   373→		}
   374→	}
   375→}
   376→
   377→void UCosmeticMainWindow::RefreshActionButton()
   378→{
   379→	if (!ActionButton || !ActionButtonText)
   380→	{
   381→		return;
   382→	}
   383→
   384→	if (SelectedItemId.IsNone())
   385→	{
   386→		ActionButton->SetIsEnabled(false);
   387→		ActionButtonText->SetText(NSLOCTEXT("Cosmetic", "SelectItem", "아이템 선택"));
   388→		return;
   389→	}
   390→
   391→	UGameInstance* GI = GetGameInstance();
   392→	if (!GI)
   393→	{
   394→		return;
   395→	}
   396→
   397→	UWjWorldCosmeticSubsystem* CosmeticSub = GI->GetSubsystem<UWjWorldCosmeticSubsystem>();
   398→	if (!CosmeticSub)
   399→	{
   400→		return;
   401→	}
   402→
   403→	const FCosmeticLoadout& Loadout = CosmeticSub->GetLoadout();
   404→	FName EquippedItem = Loadout.GetEquippedItem(CurrentSlot);
   405→	bool bIsEquipped = (EquippedItem == SelectedItemId);
   406→
   407→	if (CurrentMode == ECosmeticWindowMode::Shop)
   408→	{
   409→		// 상점 모드
   410→		if (CosmeticSub->HasItem(SelectedItemId))
   411→		{
   412→			// 보유 중인 아이템 → 장착/해제 가능
   413→			ActionButton->SetIsEnabled(true);
   414→
   415→			if (bIsEquipped)
   416→			{
   417→				ActionButtonText->SetText(NSLOCTEXT("Cosmetic", "Unequip", "해제"));
   418→			}
   419→			else
   420→			{
   421→				ActionButtonText->SetText(NSLOCTEXT("Cosmetic", "Equip", "장착"));
   422→			}
