   487→void UWjWorldCurrencySubsystem::StopExchangePolling()
   488→{
   489→	UWorld* World = GetWorld();
   490→	if (World)
   491→	{
   492→		World->GetTimerManager().ClearTimer(ExchangePollTimerHandle);
