	void OnInventoryUpdated();

	UFUNCTION()
	void OnLoadoutChanged(ECosmeticSlot CosmeticSlot, FName ItemId);

	UFUNCTION()
	void OnPurchaseComplete(FName ItemId, bool bSuccess);

private:
