void UCosmeticMainWindow::OnLoadoutChanged(ECosmeticSlot CosmeticSlot, FName ItemId)
{
	UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticMainWindow: Loadout changed, refreshing UI"));
	RefreshUI();

