void UCosmeticMainWindow::RefreshItemGrid()
{
	ClearItemGrid();

	if (CurrentMode == ECosmeticWindowMode::Shop)
	{
		PopulateShopItems();
	}
	else
	{
		PopulateInventoryItems();
	}
