	TObjectPtr<UBorder> SelectionBorder;

	/** 장착 표시 아이콘 */
	UPROPERTY(meta = (BindWidgetOptional))
	TObjectPtr<UImage> EquippedIcon;

	/** 클릭 감지 버튼 */
	UPROPERTY(meta = (BindWidget))
	TObjectPtr<UButton> ItemButton;

