   359→void UCosmeticMainWindow::RefreshDetailInfo()
   360→{
   361→	if (SelectedItemId.IsNone())
   362→	{
   363→		if (SelectedItemNameText)
   364→		{
   365→			SelectedItemNameText->SetText(FText::GetEmpty());
   366→		}
   367→		if (SelectedItemDescriptionText)
   368→		{
   369→			SelectedItemDescriptionText->SetText(FText::GetEmpty());
   370→		}
   371→		if (SelectedItemPriceText)
   372→		{
   373→			SelectedItemPriceText->SetText(FText::GetEmpty());
   374→		}
   375→		return;
   376→	}
   377→
   378→	UGameInstance* GI = GetGameInstance();
   379→	if (!GI)
   380→	{
   381→		return;
   382→	}
   383→
   384→	UWjWorldCosmeticSubsystem* CosmeticSub = GI->GetSubsystem<UWjWorldCosmeticSubsystem>();
   385→	if (!CosmeticSub || !CosmeticSub->GetCatalog())
   386→	{
   387→		return;
   388→	}
   389→
   390→	const FCosmeticItemDefinition* ItemDef = CosmeticSub->GetCatalog()->FindByItemId(SelectedItemId);
   391→	if (!ItemDef)
   392→	{
   393→		return;
   394→	}
   395→
   396→	if (SelectedItemNameText)
   397→	{
   398→		SelectedItemNameText->SetText(ItemDef->DisplayName);
   399→	}
   400→
   401→	if (SelectedItemDescriptionText)
   402→	{
   403→		SelectedItemDescriptionText->SetText(ItemDef->Description);
   404→	}
   405→
   406→	if (SelectedItemPriceText)
   407→	{
   408→		if (CosmeticSub->HasItem(SelectedItemId))
   409→		{
   410→			SelectedItemPriceText->SetText(NSLOCTEXT("Cosmetic", "Owned", "보유중"));
   411→		}
   412→		else if (ItemDef->CoinPrice > 0 && ItemDef->GemPrice > 0)
   413→		{
   414→			SelectedItemPriceText->SetText(FText::Format(
   415→				NSLOCTEXT("Cosmetic", "CoinGemPriceFormat", "{0} Coin / {1} Gem"),
   416→				FText::AsNumber(ItemDef->CoinPrice), FText::AsNumber(ItemDef->GemPrice)));
   417→		}
   418→		else if (ItemDef->CoinPrice > 0)
   419→		{
   420→			SelectedItemPriceText->SetText(FText::Format(
   421→				NSLOCTEXT("Cosmetic", "CoinPriceFormat", "{0} Coin"),
   422→				FText::AsNumber(ItemDef->CoinPrice)));
   423→		}
   424→		else if (ItemDef->GemPrice > 0)
   425→		{
   426→			SelectedItemPriceText->SetText(FText::Format(
   427→				NSLOCTEXT("Cosmetic", "GemPriceFormat", "{0} Gem"),
   428→				FText::AsNumber(ItemDef->GemPrice)));
   429→		}
   430→		else
   431→		{
   432→			SelectedItemPriceText->SetText(NSLOCTEXT("Cosmetic", "Free", "무료"));
   433→		}
   434→	}
   435→}
