   663→void UCosmeticMainWindow::PopulateInventoryItems()
   664→{
   665→	UGameInstance* GI = GetGameInstance();
   666→	if (!GI)
   667→	{
   668→		return;
   669→	}
   670→
   671→	UWjWorldCosmeticSubsystem* CosmeticSub = GI->GetSubsystem<UWjWorldCosmeticSubsystem>();
   672→	if (!CosmeticSub || !CosmeticSub->GetCatalog())
   673→	{
   674→		return;
   675→	}
   676→
   677→	UWjWorldCosmeticCatalogDataAsset* Catalog = CosmeticSub->GetCatalog();
   678→	const TArray<FCosmeticItemInstance>& Inventory = CosmeticSub->GetInventory();
   679→	const FCosmeticLoadout& Loadout = CosmeticSub->GetLoadout();
   680→
   681→	int32 Index = 0;
   682→	for (const FCosmeticItemInstance& ItemInstance : Inventory)
   683→	{
   684→		const FCosmeticItemDefinition* ItemDef = Catalog->FindByItemId(ItemInstance.ItemId);
   685→		if (!ItemDef || !ItemDef->IsValid())
   686→		{
   687→			continue;
   688→		}
   689→
   690→		// 현재 슬롯에 해당하는 아이템만 표시
   691→		if (ItemDef->Slot != CurrentSlot)
   692→		{
   693→			continue;
   694→		}
   695→
   696→		UCosmeticItemEntryWidget* EntryWidget = CreateItemEntry(*ItemDef);
   697→		if (!EntryWidget)
   698→		{
   699→			continue;
   700→		}
   701→
   702→		// 인벤토리 모드에서는 항상 보유 중
   703→		bool bEquipped = Loadout.GetEquippedItem(CurrentSlot) == ItemDef->ItemId;
   704→
   705→		EntryWidget->SetOwned(true);
   706→		EntryWidget->SetEquipped(bEquipped);
   707→		EntryWidget->SetSelected(ItemDef->ItemId == SelectedItemId);
   708→
   709→		// 그리드에 추가
   710→		if (ItemGridPanel)
   711→		{
   712→			ItemGridPanel->AddChildToUniformGrid(EntryWidget, Index / GridColumnCount, Index % GridColumnCount);
   713→		}
   714→
   715→		ItemEntryWidgets.Add(EntryWidget);
   716→		Index++;
   717→	}
   718→
   719→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticMainWindow: Populated %d inventory items"), Index);
   720→}
