   727→		return nullptr;
   728→	}
   729→
   730→	UCosmeticItemEntryWidget* EntryWidget = CreateWidget<UCosmeticItemEntryWidget>(GetOwningPlayer(), ItemEntryWidgetClass);
   731→	if (!EntryWidget)
   732→	{
   733→		return nullptr;
   734→	}
   735→
   736→	EntryWidget->SetItemDefinition(Def);
   737→	EntryWidget->OnItemClicked.AddDynamic(this, &UCosmeticMainWindow::OnItemClicked);
   738→
   739→	return EntryWidget;
   740→}
