   119→void URoomListWindow::UpdateRoomList(const TArray<FRoomInfo>& Rooms)
   120→{
   121→	if (!RoomListScrollBox)
   122→	{
   123→		UE_LOG(LogWjWorld, Error, TEXT("RoomListWindow: RoomListScrollBox is null"));
   124→		return;
   125→	}
   126→
   127→	if (!RoomListEntryWidgetClass)
   128→	{
   129→		UE_LOG(LogWjWorld, Error, TEXT("RoomListWindow: RoomListEntryWidgetClass is not set"));
   130→		return;
   131→	}
   132→
   133→	// 기존 목록 제거
   134→	RoomListScrollBox->ClearChildren();
   135→
   136→	// 방이 없으면 메시지 표시
   137→	if (Rooms.Num() == 0)
   138→	{
   139→		UE_LOG(LogWjWorld, Warning, TEXT("RoomListWindow: No rooms found"));
   140→		// TODO: "방이 없습니다" 텍스트 표시
   141→		return;
   142→	}
   143→
   144→	// 각 방에 대한 엔트리 위젯 생성
   145→	for (const FRoomInfo& RoomInfo : Rooms)
   146→	{
   147→		URoomListEntryWidget* EntryWidget = CreateWidget<URoomListEntryWidget>(GetWorld(), RoomListEntryWidgetClass);
