   158→void URoomListWindow::OnNetworkModeSelectionChanged(FString SelectedItem, ESelectInfo::Type SelectionType)
   159→{
   160→	// 프로그램적 변경은 무시 (ShowPopupWithNetworkMode에서 설정할 때)
   161→	if (SelectionType == ESelectInfo::Direct)
   162→	{
   163→		return;
   164→	}
   165→
   166→	ENetworkMode NewMode = (SelectedItem == TEXT("Steam")) ? ENetworkMode::Steam : ENetworkMode::LAN;
   167→
   168→	if (CurrentNetworkMode != NewMode)
   169→	{
   170→		CurrentNetworkMode = NewMode;
   171→		UE_LOG(LogWjWorld, Log, TEXT("RoomListWindow: Network mode changed to %s"), *SelectedItem);
   172→
   173→		// 모드 변경 시 자동으로 다시 검색
   174→		StartSearching();
   175→	}
   176→}
