   183→		return;
   184→	}
   185→
   186→	NetworkModeComboBox->ClearOptions();
   187→
   188→	// LAN 옵션 추가
   189→	NetworkModeComboBox->AddOption(TEXT("LAN"));
   190→
   191→	// Steam 옵션 추가 (Steam 빌드에서만 활성화)
   192→#if WITH_STEAM
   193→	NetworkModeComboBox->AddOption(TEXT("Steam"));
   194→#endif
   195→
   196→	// 기본값은 LAN
   197→	NetworkModeComboBox->SetSelectedOption(TEXT("LAN"));
   198→
   199→	// 콜백 바인딩
   200→	NetworkModeComboBox->OnSelectionChanged.AddDynamic(this, &URoomListWindow::OnNetworkModeSelectionChanged);
