   170→void ULobbyHUDWidget::OnPlacementContextSelected(EPlacementContext SelectedContext)
   171→{
   172→	UE_LOG(LogWjWorld, Log, TEXT("LobbyHUDWidget: Placement context selected: %s"), *GetPlacementContextName(SelectedContext));
   173→
   174→	switch (SelectedContext)
   175→	{
   176→	case EPlacementContext::Lobby:
   177→		{
   178→			// 로비 배치 모드 진입 (현재 맵에서)
   179→			AWjWorldGameModeLobby* GameMode = Cast<AWjWorldGameModeLobby>(GetWorld()->GetAuthGameMode());
   180→			if (GameMode)
   181→			{
   182→				GameMode->EnterPlacementMode();
   183→			}
   184→			else
   185→			{
   186→				UE_LOG(LogWjWorld, Error, TEXT("LobbyHUDWidget: Failed to get WjWorldGameModeLobby"));
   187→			}
   188→		}
   189→		break;
   190→
   191→	case EPlacementContext::ApproachingWall:
   192→	case EPlacementContext::JumpMap:
   193→		{
   194→			// 에디터 맵으로 이동
   195→			const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   196→			if (!Settings)
   197→			{
   198→				UE_LOG(LogWjWorld, Error, TEXT("LobbyHUDWidget: DeveloperSettings not found"));
   199→				return;
   200→			}
   201→
   202→			FString EditorMapURL = Settings->GetEditorMapOpenLevelURL(SelectedContext);
   203→			if (EditorMapURL.IsEmpty())
   204→			{
   205→				UE_LOG(LogWjWorld, Error, TEXT("LobbyHUDWidget: Editor map not configured for context %s"), *GetPlacementContextName(SelectedContext));
   206→				return;
   207→			}
   208→
   209→			UE_LOG(LogWjWorld, Log, TEXT("LobbyHUDWidget: Opening editor map: %s"), *EditorMapURL);
   210→			UGameplayStatics::OpenLevel(this, *EditorMapURL);
   211→		}
   212→		break;
   213→
   214→	default:
   215→		UE_LOG(LogWjWorld, Warning, TEXT("LobbyHUDWidget: Unknown placement context"));
   216→		break;
   217→	}
