   169→void AWjWorldGameModeLobby::EnterPlacementMode()
   170→{
   171→	APlayerController* PC = GetWorld()->GetFirstPlayerController();
   172→	AWjWorldPlayerControllerLobby* LobbyPC = Cast<AWjWorldPlayerControllerLobby>(PC);
   173→	if (!LobbyPC)
   174→	{
   175→		return;
   176→	}
   177→
   178→	// 호스트만 배치 모드 진입 가능
   179→	if (!IsHost(LobbyPC))
   180→	{
   181→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("WjWorldGameModeLobby: Only host can enter placement mode"));
   182→		return;
   183→	}
   184→
   185→	UWjWorldPlacementComponent* PlacementComp = LobbyPC->GetPlacementComponent();
   186→	if (!PlacementComp)
   187→	{
   188→		return;
   189→	}
   190→
   191→	// 1. 카메라 Pawn으로 전환 (Possess → 새 InputComponent)
   192→	LobbyPC->SwitchToPlacementCamera();
   193→
   194→	// 2. 배치 모드 시작 (새 InputComponent에 바인딩)
   195→	PlacementComp->EnterPlacementMode();
   196→
   197→	// 3. 모드 변경 델리게이트 구독 (ESC 종료 시 카메라 복귀용)
   198→	PlacementComp->OnPlacementModeChanged.AddDynamic(
   199→		this, &AWjWorldGameModeLobby::HandlePlacementModeChanged);
   200→
   201→	// 4. HUD 전환
   202→	AWjWorldHUDLobby* LobbyHUD = Cast<AWjWorldHUDLobby>(LobbyPC->GetHUD());
   203→	if (LobbyHUD)
   204→	{
   205→		LobbyHUD->ShowPlacementHUD(PlacementComp);
   206→	}
   207→
   208→	UE_LOG(LogWjWorldPlacement, Log, TEXT("WjWorldGameModeLobby: Entered placement mode (Host) with camera pawn"));
   209→}
